<?php
/* GSAP e ScrollTrigger sono ospitati qui invece che su un CDN esterno.
   Motivo: la CSP consente gli script solo da 'self' e da cdn.jsdelivr.net,
   mentre questi arrivavano da cdnjs.cloudflare.com — venivano bloccati, e con
   loro spariva tutta l'animazione della sezione «La scienza».
   Ospitandoli si evita di allargare la policy e si toglie una dipendenza da un
   sito di terzi che potrebbe cambiare o sparire. */
?>
<script src="<?php echo PWA_BASE; ?>_assets/vendor/gsap.min.js"></script>



<script src="<?php echo PWA_BASE; ?>_assets/vendor/ScrollTrigger.min.js"></script>



<script>



/* Animazione "le carte cadono, formano il rettangolo e poi il cervello" */



(function(){



if (typeof gsap === 'undefined' || typeof ScrollTrigger === 'undefined') return;



if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;



const storySection = document.getElementById('nlStory');



const cardsHost = document.getElementById('nlStoryCards');



const brainPath = document.getElementById('brain-path');



if (!storySection || !cardsHost || !brainPath) return;







gsap.registerPlugin(ScrollTrigger);







// Distinzione netta tra smartphone e PC



const isMobile = window.innerWidth < 640;



// Aumentate le carte su mobile per riempire meglio il cervello e il rettangolo



const totalCards = isMobile ? 280 : 400;



const pathLength = brainPath.getTotalLength();



const cardsArray = [];







for (let i = 0; i < totalCards; i++) {



const card = document.createElement('div');



card.className = 'nl-story-card';







// A. INIZIO: Partono sparpagliate altissime



const startX = 50 + (Math.random() - 0.5) * 120;



const startY = -40 - Math.random() * 60;



const startRot = Math.random() * 360;







// B. VOLO INIZIALE (1° frase)



const flyX = 50 + (Math.random() - 0.5) * 90;



const flyY = 20 + Math.random() * 60;







// C. RETTANGOLO (2° frase)



let rectX, rectY;



const edge = Math.floor(Math.random() * 4);






/* === CONTROLLI RETTANGOLO === */



// BARRA SINISTRA: alza il primo numero per stringerla verso il centro (es. da 12 a 15)



const minX = isMobile ? 20 : 4;






// BARRA DESTRA: abbassa il primo numero per stringerla verso il centro (es. da 88 a 85)



const maxX = isMobile ? 85 : 96;






// ALTEZZA (SOPRA E SOTTO): alza entrambi i primi numeri per spingere il rettangolo PIÙ IN BASSO



const minY = isMobile ? 22 : 25; // Era 18, proviamo 22



const maxY = isMobile ? 86 : 75; // Era 82, proviamo 86






const thickness = isMobile ? 4 : 5;







if (edge === 0) { // Bordo Sopra



rectX = minX + Math.random() * (maxX - minX);



rectY = minY + (Math.random() * thickness - thickness/2);



} else if (edge === 1) { // Bordo Sotto



rectX = minX + Math.random() * (maxX - minX);



rectY = maxY + (Math.random() * thickness - thickness/2);



} else if (edge === 2) { // Bordo Sinistra



rectX = minX + (Math.random() * thickness - thickness/2);



rectY = minY + Math.random() * (maxY - minY);



} else { // Bordo Destra



rectX = maxX + (Math.random() * thickness - thickness/2);



rectY = minY + Math.random() * (maxY - minY);



}







// D. CERVELLO: Coordinate matematiche nel cranio



const randomLength = Math.random() * pathLength;



const point = brainPath.getPointAtLength(randomLength);



const scale = 0.60;






/* === CONTROLLI CERVELLO === */



const offsetXPercent = isMobile ? 24 : 21.7;






// ALTEZZA CERVELLO: alza il primo numero per spostarlo PIÙ IN BASSO su smartphone



const offsetYPercent = isMobile ? 8 : 5; // Prima era 5 per tutti, proviamo 8 per mobile






const brainX = (((point.x * scale) + (Math.random() - 0.5) * 4) / 1387) * 100 + offsetXPercent;



const brainY = (((point.y * scale) + (Math.random() - 0.5) * 4) / 756) * 100 + offsetYPercent;



const brainRot = (Math.random() - 0.5) * 90;







gsap.set(card, {



left: `${startX}%`, top: `${startY}%`, rotation: startRot,



xPercent: -50, yPercent: -50, opacity: 0



});







cardsHost.appendChild(card);



cardsArray.push({ el: card, flyX, flyY, rectX, rectY, brainX, brainY, brainRot });



}







// Nascondiamo solo la seconda e terza frase, la prima (data-step="0") la rendiamo GIA' visibile!
  gsap.set('.nl-story-step[data-step="1"], .nl-story-step[data-step="2"]', { opacity: 0, y: 30 });
  gsap.set('.nl-story-step[data-step="0"]', { opacity: 1, y: 0 });

  // TIMELINE PRINCIPALE
  const tl = gsap.timeline({
    scrollTrigger: {
      trigger: storySection, start: 'top top', end: 'bottom bottom',
      scrub: 0.8, pin: '.nl-story-pin'
    }
  });

  // (FASE 0 eliminata: non serve più farla comparire perché c'è già)

  // FASE 1: Mentre c'è la prima frase con il grafico, le carte PIOVONO sparpagliate
  cardsArray.forEach((c) => {
    const delay = Math.random() * 1.5; // Abbassato per non aspettare troppo
    tl.to(c.el, { 
      left: `${c.flyX}%`, top: `${c.flyY}%`, 
      rotation: "+=240", rotationX: "+=180", rotationY: "+=180", 
      opacity: 0.2, 
      duration: 1.5, ease: 'power1.out' 
    }, delay);
  });

  // FASE 2: Scompare la 1° frase (con grafico), appare la 2° frase
  tl.to('.nl-story-step[data-step="0"]', { opacity: 0, y: -20, duration: 0.4 }, 2.5);
  tl.to('.nl-story-step[data-step="1"]', { opacity: 1, y: 0, duration: 0.4 }, 2.8);

  // FASE 3: RETTANGOLO (Anticipato!)
  // Le carte iniziano ad allinearsi GIA' dal tempo 2.1, cioè PRIMA che la frase precedente sia sparita del tutto.
  cardsArray.forEach((c) => {
    const delay = 2.1 + Math.random() * 0.5; // Prima era 2.8, abbassando questo numero partono prima!
    tl.to(c.el, { 
      left: `${c.rectX}%`, top: `${c.rectY}%`, 
      rotation: "+=180", rotationX: "+=180", 
      opacity: 0.4, 
      duration: 1.2, ease: 'power2.inOut' 
    }, delay);
  });

  // FASE 4: CERVELLO (le carte partono in forte anticipo, abbandonando il rettangolo)
  cardsArray.forEach((c) => {
    // Partono a 4.3, ben prima che la frase sparisca
    const delay = 4.3 + Math.random() * 0.2; 
    tl.to(c.el, { 
      left: `${c.brainX}%`, top: `${c.brainY}%`, 
      rotation: c.brainRot, rotationX: 0, rotationY: 0,
      opacity: 1, 
      duration: 1.2, ease: 'power3.inOut' 
    }, delay);
  });

  // FASE 5: Scompare la 2° frase e appare la sagoma della Testa
  // Avviene a 4.6, quindi MENTRE le carte sono già in viaggio!
  tl.to('.nl-story-step[data-step="1"]', { opacity: 0, y: -20, duration: 0.4 }, 4.6);
  tl.to('.nl-story-head', { opacity: 1, duration: 0.5 }, 4.6);

  // FASE 6: Appare la frase finale ("Non un ripasso") sotto la testa
  tl.to('.nl-story-step[data-step="2"]', { opacity: 1, y: 0, duration: 0.5 }, 5.8);

  ScrollTrigger.refresh();
})();
</script>







<script>



(function(){



function nisamaRenderTags(root) {



root.querySelectorAll('[data-nisama-tags]').forEach(el => {



let html = el.textContent;



['red','blue','green','purple','orange','gray','yellow'].forEach(c => {



html = html.replace(new RegExp('/' + c + '\\{([^}]*)\\}', 'g'), '<span class="nl-hl nl-hl--' + c + '">$1</span>');



});



html = html.replace(/\/bold\{([^}]*)\}/g, '<strong>$1</strong>');



html = html.replace(/\/italic\{([^}]*)\}/g, '<em>$1</em>');



html = html.replace(/\/underline\{([^}]*)\}/g, '<u>$1</u>');



el.innerHTML = html;



});



}



nisamaRenderTags(document);







const revealEls = document.querySelectorAll('.nisama-landing .reveal');



if ('IntersectionObserver' in window) {



const groups = ['.nl-features .reveal', '.nl-quotes .reveal', '.nl-compare .reveal'];



groups.forEach(sel => {



document.querySelectorAll(sel).forEach((el, i) => { el.style.transitionDelay = (i * 90) + 'ms'; });



});



const io = new IntersectionObserver((entries) => {



entries.forEach(entry => {



if (entry.isIntersecting) { entry.target.classList.add('revealed'); io.unobserve(entry.target); }



});



}, { threshold: 0.15 });



revealEls.forEach(el => io.observe(el));



} else {



revealEls.forEach(el => el.classList.add('revealed'));



}







const flip = document.getElementById('nlFlipCard');



if (flip) {



const toggleFlip = () => flip.classList.toggle('is-flipped');



flip.addEventListener('click', toggleFlip);



flip.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleFlip(); } });



setTimeout(() => { if (!flip.classList.contains('is-flipped')) flip.classList.add('is-flipped'); }, 1400);



setTimeout(() => { flip.classList.remove('is-flipped'); }, 3200);



}







const chart = document.getElementById('nlChart');



if (chart && 'IntersectionObserver' in window) {



const paths = [document.getElementById('nlPathPassive'), document.getElementById('nlPathActive')];



paths.forEach(p => { p.style.strokeDasharray = 900; p.style.strokeDashoffset = 900; });



const chartIo = new IntersectionObserver((entries) => {



entries.forEach(entry => {



if (entry.isIntersecting) {



paths.forEach((p, i) => {



p.style.transition = 'stroke-dashoffset 1.6s ' + (i * 0.25) + 's cubic-bezier(.22,1,.36,1)';



p.style.strokeDashoffset = 0;



});



chartIo.unobserve(entry.target);



}



});



}, { threshold: 0.3 });



chartIo.observe(chart);



}



})();



</script> 

